sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float amount;
uniform float noiseCut;
uniform float lumaOnly;
uniform float haloLimit;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 b = unp(float4(blurred.eval(coord)));
    float3 d = s - b;
    if (lumaOnly > 0.5) d = float3(luma(s) - luma(b));
    float gate = smoothstep(0.0, noiseCut + 0.0001, abs(luma(s) - luma(b)));
    d = clamp(d, float3(-haloLimit), float3(haloLimit));
    float3 o = s + d * amount * gate;
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
